import { errors } from "@appport/protocol";
import { readExport } from "../legacy/crm.mjs";

// Who to send a customer's invoices to.
//
// Reads customer rows from the CRM export (readExport) directly, instead of going
// through lookupCustomer in ./customers.lookup.mjs.
//
// Assumption: readExport is the application's customer store. It is the only
// customer data source visible to this module. If the application has a different
// customer store, this module should read from that store instead.
//
// Equivalence with the previous implementation:
//   - Same row matching: the first row whose cust_id === input.customerId.
//   - Same field mapping: cust_id, full_name and mail.
//   - Same failure: errors.notFound with the identical message.
// The tier and since fields were never returned by billing.contact@1, so they are
// not read here. Unlike the old code, this avoids the TIERS lookup.
//
// Note for the contract owner: the published contract still declares
// requires: customers.lookup@1 (observes). This implementation no longer calls that
// code. The contract was left unchanged, as instructed.
export async function billingContact(input, context) {
  const row = readExport().find((r) => r.cust_id === input.customerId);
  if (!row) {
    throw errors.notFound(`no customer ${input.customerId}`);
  }
  return { customerId: row.cust_id, name: row.full_name, email: row.mail };
}
